package android.app;import android.content.*;public class AlertDialog extends Dialog {public static String[] items;public static DialogInterface.OnClickListener click;public static int count,theme;public static Context context;public static boolean fail; public static class Builder {public Builder(Context c){context=c;theme=0;}public Builder(Context c,int t){context=c;theme=t;}public Builder setItems(CharSequence[] a,DialogInterface.OnClickListener l){items=new String[a.length];for(int i=0;i<a.length;i++)items[i]=a[i].toString();click=l;return this;}public AlertDialog show(){if(!(context instanceof Activity))throw new android.view.WindowManager.BadTokenException("token null");if(fail)throw new IllegalArgumentException("fixture menu failure");count++;return new AlertDialog();}}}
